package main

import (
	"context"
	"encoding/base64"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"

	"github.com/wailsapp/wails/v2/pkg/runtime"

	"paper-scan-processor/backend/drive"
	"paper-scan-processor/backend/filetree"
	"paper-scan-processor/backend/pdf"
)

// App struct
type App struct {
	ctx context.Context
}

// NewApp creates a new App application struct
func NewApp() *App {
	return &App{}
}

// startup is called when the app starts. The context is saved
// so we can call the runtime methods
func (a *App) startup(ctx context.Context) {
	a.ctx = ctx
}

// OpenPDF shows a file-open dialog filtered to PDFs and returns the selected path.
// Returns an empty string if the user cancels.
func (a *App) OpenPDF() (string, error) {
	path, err := runtime.OpenFileDialog(a.ctx, runtime.OpenDialogOptions{
		Title: "Open PDF",
		Filters: []runtime.FileFilter{
			{DisplayName: "PDF Files (*.pdf)", Pattern: "*.pdf"},
		},
	})
	return path, err
}

// PageCount returns the number of pages in the PDF at path.
func (a *App) PageCount(path string) (int, error) {
	return pdf.PageCount(path)
}

// RenderPage renders a single page of the PDF at path as a PNG and returns it
// base64-encoded. widthPx controls the output width; height is scaled proportionally.
func (a *App) RenderPage(path string, pageNum int, widthPx int) (string, error) {
	tmpDir, err := os.MkdirTemp("", "psp-render-*")
	if err != nil {
		return "", err
	}
	defer os.RemoveAll(tmpDir)

	outPrefix := filepath.Join(tmpDir, "page")
	page := strconv.Itoa(pageNum)

	out, err := exec.Command(
		"pdftoppm",
		"-f", page,
		"-l", page,
		"-singlefile",
		"-png",
		"-scale-to-x", strconv.Itoa(widthPx),
		"-scale-to-y", "-1",
		path,
		outPrefix,
	).CombinedOutput()
	if err != nil {
		return "", fmt.Errorf("pdftoppm: %w\n%s", err, out)
	}

	data, err := os.ReadFile(outPrefix + ".png")
	if err != nil {
		return "", err
	}
	return base64.StdEncoding.EncodeToString(data), nil
}

// SavePDF shows a save-file dialog filtered to PDFs and returns the chosen path.
// Returns an empty string if the user cancels.
func (a *App) SavePDF() (string, error) {
	path, err := runtime.SaveFileDialog(a.ctx, runtime.SaveDialogOptions{
		Title:           "Save Merged PDF",
		DefaultFilename: "merged.pdf",
		Filters: []runtime.FileFilter{
			{DisplayName: "PDF Files (*.pdf)", Pattern: "*.pdf"},
		},
	})
	if err != nil || path == "" {
		return path, err
	}
	if !strings.HasSuffix(strings.ToLower(path), ".pdf") {
		path += ".pdf"
	}
	return path, nil
}

// OpenFile opens the file at path with the system default application.
func (a *App) OpenFile(path string) error {
	return exec.Command("open", path).Run()
}

// DeleteFile removes the file at path.
func (a *App) DeleteFile(path string) error {
	return os.Remove(path)
}

// MergePDFs interleaves pages from pathA and pathB and writes the result to outPath.
func (a *App) MergePDFs(pathA, pathB, outPath string, firstPageInA, reverseB bool, skipA, skipB []int, rotationsA, rotationsB map[int]int) error {
	return pdf.MergePDFs(pathA, pathB, outPath, firstPageInA, reverseB, skipA, skipB, rotationsA, rotationsB)
}

// PickFolder shows a folder-select dialog with the given title and returns
// the chosen path. Returns an empty string if the user cancels.
func (a *App) PickFolder(title string) (string, error) {
	return runtime.OpenDirectoryDialog(a.ctx, runtime.OpenDialogOptions{
		Title: title,
	})
}

// ScanLocalRoot recursively scans root and returns it as a LocalFileGroup
// tree (nested to match the folder structure), with size and page count
// metadata for each file.
func (a *App) ScanLocalRoot(root string) (filetree.LocalFileGroup, error) {
	return filetree.ScanLocalRoot(root)
}

// ListDriveFolder returns the direct children of the Drive folder with the
// given ID ("root" for the top level of My Drive), folders first then
// files. Triggers the OAuth flow on first use if no token is cached yet.
func (a *App) ListDriveFolder(folderID string) ([]drive.Item, error) {
	return drive.ListFolder(a.ctx, folderID)
}

// outputFileDest returns the destination path for the i-th pdf.OutputFileSpec.
func outputFileDest(files []pdf.OutputFileSpec, i int) string {
	name := strings.TrimSpace(files[i].Name)
	if name == "" {
		name = fmt.Sprintf("output-%d", i+1)
	}
	if !strings.HasSuffix(strings.ToLower(name), ".pdf") {
		name += ".pdf"
	}
	return filepath.Join(files[i].OutDir, name)
}

// CheckConflicts returns the destination paths that already exist on disk.
func (a *App) CheckConflicts(files []pdf.OutputFileSpec) ([]string, error) {
	conflicts := []string{}
	for i := range files {
		dest := outputFileDest(files, i)
		if _, err := os.Stat(dest); err == nil {
			conflicts = append(conflicts, dest)
		}
	}
	return conflicts, nil
}

// ExportSplit splits the PDF at inPath according to files and writes each
// segment to its OutDir using its Name.
// Each file's Pages lists the original (1-indexed) page numbers in display
// order; skip filtering and reordering have already been applied by the caller.
// rotations maps 1-indexed page numbers to clockwise degrees (90, 180, 270).
func (a *App) ExportSplit(inPath string, files []pdf.OutputFileSpec, rotations map[int]int) error {
	tmpDir, err := os.MkdirTemp("", "psp-split-*")
	if err != nil {
		return err
	}
	defer os.RemoveAll(tmpDir)

	paths, err := pdf.SplitPDF(inPath, files, rotations, tmpDir)
	if err != nil {
		return err
	}

	for i, src := range paths {
		if err := pdf.CopyFile(src, outputFileDest(files, i)); err != nil {
			return err
		}
	}
	return nil
}

import { useState, useCallback } from 'react'
import { PickFolder, ScanLocalRoot } from '../../../wailsjs/go/main/App'

export interface LocalFile {
  path: string
  name: string
  sizeBytes: number
  isPdf: boolean
  pageCount: number
  corrupt: boolean
}

export interface LocalFileGroup {
  name: string
  files: LocalFile[]
  subgroups: LocalFileGroup[]
}

export interface FileTreeHandle {
  root: string | null
  tree: LocalFileGroup | null
  loading: boolean
  error: string | null
  pickRoot: () => Promise<void>
}

export function useFileTree(): FileTreeHandle {
  const [root, setRoot] = useState<string | null>(null)
  const [tree, setTree] = useState<LocalFileGroup | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const pickRoot = useCallback(async () => {
    const folder = await PickFolder('Choose Root Folder')
    if (!folder) return

    setRoot(folder)
    setLoading(true)
    setError(null)
    try {
      setTree(await ScanLocalRoot(folder))
    } catch (e) {
      setTree(null)
      setError(String(e))
    } finally {
      setLoading(false)
    }
  }, [])

  return { root, tree, loading, error, pickRoot }
}

import { useState, useCallback } from 'react'

export interface DriveAssignment {
  driveFolderId: string
  path: string
}

// Identifies what a picked Drive folder should be applied to: a subfolder
// group (by its path key) or an individual file (by its filesystem path).
export type PickerTarget = { type: 'group'; key: string } | { type: 'file'; path: string }

export interface DriveAssignmentsHandle {
  groupAssignments: Map<string, DriveAssignment>
  fileOverrides: Map<string, DriveAssignment>
  setGroupAssignment: (groupKey: string, assignment: DriveAssignment) => void
  clearGroupAssignment: (groupKey: string) => void
  setFileOverride: (filePath: string, assignment: DriveAssignment) => void
  clearFileOverride: (filePath: string) => void
}

// Tracks Drive folder assignments made directly on a subfolder group or on
// an individual file (a file-level assignment overrides its group's).
// Resolving the *effective* assignment for a given group/file (own, else
// inherited from the nearest ancestor group, else none) is the caller's
// job, since only the caller knows the tree structure to walk.
export function useDriveAssignments(): DriveAssignmentsHandle {
  const [groupAssignments, setGroupAssignments] = useState<Map<string, DriveAssignment>>(new Map())
  const [fileOverrides, setFileOverrides] = useState<Map<string, DriveAssignment>>(new Map())

  const setGroupAssignment = useCallback((groupKey: string, assignment: DriveAssignment) => {
    setGroupAssignments(prev => new Map(prev).set(groupKey, assignment))
  }, [])

  const clearGroupAssignment = useCallback((groupKey: string) => {
    setGroupAssignments(prev => {
      const next = new Map(prev)
      next.delete(groupKey)
      return next
    })
  }, [])

  const setFileOverride = useCallback((filePath: string, assignment: DriveAssignment) => {
    setFileOverrides(prev => new Map(prev).set(filePath, assignment))
  }, [])

  const clearFileOverride = useCallback((filePath: string) => {
    setFileOverrides(prev => {
      const next = new Map(prev)
      next.delete(filePath)
      return next
    })
  }, [])

  return { groupAssignments, fileOverrides, setGroupAssignment, clearGroupAssignment, setFileOverride, clearFileOverride }
}

