import { useCallback, useRef, useState } from 'react'
import { UploadFile } from '../../../wailsjs/go/main/App'

export type UploadStatus = 'idle' | 'queued' | 'uploading' | 'done' | 'error'

export interface UploadFileState {
  status: UploadStatus
  error?: string
}

export interface UploadJob {
  path: string
  folderId: string
  name: string
}

export interface UploadQueueHandle {
  statuses: Map<string, UploadFileState>
  start: (jobs: UploadJob[]) => void
  retry: (job: UploadJob) => void
  cancelRemaining: () => void
  reset: () => void
}

// Per-file upload status, driven by a sequential (concurrency = 1) worker.
// Callers resolve each file's destination folder/name up front and pass in
// an ordered list of jobs — this hook only knows how to run them one at a
// time and track status, not about the file tree or Drive assignments.
export function useUploadQueue(): UploadQueueHandle {
  const [statuses, setStatuses] = useState<Map<string, UploadFileState>>(new Map())
  const jobsRef = useRef<Map<string, UploadJob>>(new Map())
  const pendingRef = useRef<string[]>([])
  const runningRef = useRef(false)
  const cancelledRef = useRef(false)
  // Bumped by reset() so a job that was already in flight can't write a
  // stale status back into the map after the run it belonged to was wiped.
  const genRef = useRef(0)

  const setStatus = useCallback((path: string, state: UploadFileState) => {
    setStatuses(prev => new Map(prev).set(path, state))
  }, [])

  const runQueue = useCallback(async (gen: number) => {
    if (runningRef.current) return
    runningRef.current = true
    while (!cancelledRef.current && genRef.current === gen && pendingRef.current.length > 0) {
      const path = pendingRef.current.shift()!
      const job = jobsRef.current.get(path)
      if (!job) continue
      setStatus(path, { status: 'uploading' })
      try {
        await UploadFile(job.path, job.folderId, job.name)
        if (genRef.current !== gen) break
        setStatus(path, { status: 'done' })
      } catch (e) {
        if (genRef.current !== gen) break
        setStatus(path, { status: 'error', error: String(e) })
      }
    }
    runningRef.current = false
  }, [setStatus])

  const enqueue = useCallback((jobs: UploadJob[]) => {
    if (jobs.length === 0) return
    cancelledRef.current = false
    setStatuses(prev => {
      const next = new Map(prev)
      for (const job of jobs) next.set(job.path, { status: 'queued' })
      return next
    })
    for (const job of jobs) {
      jobsRef.current.set(job.path, job)
      pendingRef.current.push(job.path)
    }
    void runQueue(genRef.current)
  }, [runQueue])

  const start = useCallback((jobs: UploadJob[]) => enqueue(jobs), [enqueue])
  const retry = useCallback((job: UploadJob) => enqueue([job]), [enqueue])

  // Stops starting new files; does not abort an in-flight request. Files
  // still waiting their turn go back to idle since they were never attempted.
  const cancelRemaining = useCallback(() => {
    cancelledRef.current = true
    const skipped = pendingRef.current
    pendingRef.current = []
    setStatuses(prev => {
      const next = new Map(prev)
      for (const path of skipped) next.set(path, { status: 'idle' })
      return next
    })
  }, [])

  const reset = useCallback(() => {
    genRef.current += 1
    cancelledRef.current = true
    jobsRef.current = new Map()
    pendingRef.current = []
    setStatuses(new Map())
  }, [])

  return { statuses, start, retry, cancelRemaining, reset }
}

