import { describe, it, expect, vi, beforeEach } from 'vitest'
import { act, renderHook, waitFor } from '@testing-library/react'
import { useUploadQueue, UploadJob } from './useUploadQueue'
import { UploadFile } from '../../../wailsjs/go/main/App'

vi.mock('../../../wailsjs/go/main/App', () => ({
  UploadFile: vi.fn(),
}))

function deferred<T>() {
  let resolve!: (v: T) => void
  let reject!: (e: unknown) => void
  const promise = new Promise<T>((res, rej) => { resolve = res; reject = rej })
  return { promise, resolve, reject }
}

const jobA: UploadJob = { path: '/root/a.pdf', folderId: 'f1', name: 'a.pdf' }
const jobB: UploadJob = { path: '/root/b.pdf', folderId: 'f1', name: 'b.pdf' }

describe('useUploadQueue', () => {
  beforeEach(() => {
    vi.mocked(UploadFile).mockReset()
  })

  it('starts with no statuses', () => {
    const { result } = renderHook(() => useUploadQueue())
    expect(result.current.statuses.size).toBe(0)
  })

  it('runs jobs sequentially, one uploading at a time', async () => {
    const first = deferred<string>()
    const second = deferred<string>()
    vi.mocked(UploadFile).mockReturnValueOnce(first.promise).mockReturnValueOnce(second.promise)

    const { result } = renderHook(() => useUploadQueue())
    act(() => result.current.start([jobA, jobB]))

    await waitFor(() => expect(result.current.statuses.get(jobA.path)?.status).toBe('uploading'))
    expect(result.current.statuses.get(jobB.path)?.status).toBe('queued')
    expect(UploadFile).toHaveBeenCalledTimes(1)

    await act(async () => { first.resolve('id-a') })
    await waitFor(() => expect(result.current.statuses.get(jobA.path)?.status).toBe('done'))
    await waitFor(() => expect(result.current.statuses.get(jobB.path)?.status).toBe('uploading'))
    expect(UploadFile).toHaveBeenCalledTimes(2)

    await act(async () => { second.resolve('id-b') })
    await waitFor(() => expect(result.current.statuses.get(jobB.path)?.status).toBe('done'))
  })

  it('marks a failed upload as error with a message', async () => {
    vi.mocked(UploadFile).mockRejectedValueOnce(new Error('quota exceeded'))
    const { result } = renderHook(() => useUploadQueue())

    await act(async () => { result.current.start([jobA]) })

    await waitFor(() => expect(result.current.statuses.get(jobA.path)?.status).toBe('error'))
    expect(result.current.statuses.get(jobA.path)?.error).toContain('quota exceeded')
  })

  it('retry re-queues just that file', async () => {
    vi.mocked(UploadFile).mockRejectedValueOnce(new Error('fail'))
    const { result } = renderHook(() => useUploadQueue())
    await act(async () => { result.current.start([jobA]) })
    await waitFor(() => expect(result.current.statuses.get(jobA.path)?.status).toBe('error'))

    vi.mocked(UploadFile).mockResolvedValueOnce('id-a')
    await act(async () => { result.current.retry(jobA) })

    await waitFor(() => expect(result.current.statuses.get(jobA.path)?.status).toBe('done'))
    expect(UploadFile).toHaveBeenCalledTimes(2)
  })

  it('cancelRemaining stops starting new files and reverts queued files to idle', async () => {
    const first = deferred<string>()
    vi.mocked(UploadFile).mockReturnValueOnce(first.promise)

    const { result } = renderHook(() => useUploadQueue())
    act(() => result.current.start([jobA, jobB]))
    await waitFor(() => expect(result.current.statuses.get(jobA.path)?.status).toBe('uploading'))

    act(() => result.current.cancelRemaining())
    expect(result.current.statuses.get(jobB.path)?.status).toBe('idle')

    await act(async () => { first.resolve('id-a') })
    await waitFor(() => expect(result.current.statuses.get(jobA.path)?.status).toBe('done'))
    expect(UploadFile).toHaveBeenCalledTimes(1)
  })

  it('reset clears all statuses and ignores a stale in-flight resolution', async () => {
    const first = deferred<string>()
    vi.mocked(UploadFile).mockReturnValueOnce(first.promise)

    const { result } = renderHook(() => useUploadQueue())
    act(() => result.current.start([jobA]))
    await waitFor(() => expect(result.current.statuses.get(jobA.path)?.status).toBe('uploading'))

    act(() => result.current.reset())
    expect(result.current.statuses.size).toBe(0)

    await act(async () => { first.resolve('id-a') })
    expect(result.current.statuses.size).toBe(0)
  })
})

