170	// order; skip filtering and reordering have already been applied by the caller.
171	// rotations maps 1-indexed page numbers to clockwise degrees (90, 180, 270).
172	func (a *App) ExportSplit(inPath string, files []pdf.OutputFileSpec, rotations map[int]int) error {
173		tmpDir, err := os.MkdirTemp("", "psp-split-*")
174		if err != nil {
175			return err
176		}
177		defer os.RemoveAll(tmpDir)
178	
179		paths, err := pdf.SplitPDF(inPath, files, rotations, tmpDir)
180		if err != nil {
181			return err
182		}
183	
184		for i, src := range paths {
185			if err := pdf.CopyFile(src, outputFileDest(files, i)); err != nil {
186				return err
187			}
188		}
189		return nil
190	}

11	}
